"""Forecast-only PV candidate: fixed 75% V36 + 25% V48, source-only delivery."""
import json, os, types
from pathlib import Path
import numpy as np
import pandas as pd

PIPELINE_VERSION = 'v59_v36_075_v48_025_20260915'
MANIFEST_NAME = 'meta.json'
WEIGHT = 0.25
_COMPONENTS = None

def script_dir():
    p = Path(__file__).resolve().parent
    return p.parent if p.name == 'utils' else p

def model_dir():
    return Path(os.environ.get('PV_COMBINATION_MODEL_DIR', script_dir()/'model/pv_models_v59_complementary'))

def _components():
    global _COMPONENTS
    if _COMPONENTS is None:
        modules=[]
        for name,source in [('pv_component_v36',_SOURCE_V36),('pv_component_v48',_SOURCE_V48)]:
            m=types.ModuleType(name);m.__file__=__file__;exec(compile(source,__file__+':'+name,'exec'),m.__dict__);modules.append(m)
        _COMPONENTS=tuple(modules)
    return _COMPONENTS

def train_pv_model():
    a,b=_components()
    # Both original recipes validate and reuse complete compatible local models;
    # otherwise their original full training entry points run from official data.
    a.train_pv_model();b.train_pv_model()
    meta=dict(pipeline=PIPELINE_VERSION,weight=WEIGHT,train_end='2025-09-30',policy='forecast_only',
              v36=a.PIPELINE_VERSION,v48=b.PIPELINE_VERSION)
    dest=model_dir();dest.mkdir(parents=True,exist_ok=True)
    path=dest/MANIFEST_NAME;temp=path.with_suffix('.tmp')
    temp.write_text(json.dumps(meta,indent=2),encoding='utf-8');temp.replace(path)
    return path

def _ordered(frame):
    f=frame[['pv_id','date','pred']].copy();f['date']=pd.to_datetime(f.date)
    wanted=pd.MultiIndex.from_product([sorted('pv_'+str(i) for i in range(1,101)),pd.date_range('2025-10-01','2025-10-31')],names=['pv_id','date'])
    if len(f)!=3100 or f.duplicated(['pv_id','date']).any():raise ValueError('PV candidate duplicate or missing keys')
    f=f.set_index(['pv_id','date'])
    if len(wanted.difference(f.index)) or len(f.index.difference(wanted)):raise ValueError('PV candidate unexpected keys')
    f=f.reindex(wanted)
    if not np.isfinite(f.pred.to_numpy()).all() or (f.pred<0).any():raise ValueError('PV candidate invalid prediction')
    return f

def predict_pv_model(save_output=True,mode=None):
    if mode is not None:raise ValueError('PV candidate uses its fixed recipe; omit mode')
    meta=json.loads((model_dir()/MANIFEST_NAME).read_text())
    a,b=_components()
    expected=dict(pipeline=PIPELINE_VERSION,weight=WEIGHT,train_end='2025-09-30',policy='forecast_only',v36=a.PIPELINE_VERSION,v48=b.PIPELINE_VERSION)
    if meta!=expected:raise ValueError('PV candidate manifest mismatch; run train_pv_model')
    x=_ordered(a.predict_pv_model(save_output=False));y=_ordered(b.predict_pv_model(save_output=False))
    result=x.copy();result['pred']=(1-WEIGHT)*x.pred.to_numpy()+WEIGHT*y.pred.to_numpy()
    result=result.reset_index();result['date']=result.date.dt.strftime('%Y/%m/%d')
    result['order']=result.pv_id.str.split('_').str[-1].astype(int)
    result=result.sort_values(['order','date']).drop(columns='order').reset_index(drop=True)
    if save_output:
        out=Path(os.environ.get('OUTPUT_DIR',script_dir()/'output/pv_load_forecasting'));out.mkdir(parents=True,exist_ok=True)
        result.to_csv(out/'submit_result.csv',index=False,encoding='utf-8-sig')
    print('[PV candidate] fixed 75% V36 + 25% V48; rows=3100; online validation pending',flush=True)
    return result


